using AeroScience.Missions;
using AeroScience.Shared;
using Microsoft.Data.Sqlite;
using System.Text;
using System.Text.Json;
using Xunit;
namespace AeroScience.Tests;

public sealed class MissionTimelineTests : IDisposable
{
    readonly string root=Path.Combine(Path.GetTempPath(),"aeroscience-p22-"+Guid.NewGuid());
    readonly MissionStore store;readonly ScienceStore science;readonly MissionCoordinator coordinator;
    readonly Mission flight;readonly PersonalResearchCard card;
    readonly DateTimeOffset start=DateTimeOffset.Parse("2026-10-28T00:00:00Z");DateTimeOffset time;
    public MissionTimelineTests(){var settings=new StorageManager(new PreferenceStore(root)).Initialize();store=new(Path.Combine(settings.MissionDirectory,"missions.db"));store.Initialize();science=new(settings.ScienceLibraryDirectory);science.Initialize();store.ScienceLibrary=science;var research=new ResearchOperations(store,science);coordinator=new(store,1000,research:research,utcNow:()=>time);card=store.SaveResearchCard(new("P22 original card",new(120,5,3000,100,2)));var plan=store.SavePlan(new(Guid.NewGuid(),"P22 original plan",Instruments:[new("ambient-temperature",true)],ResearchCards:[new(card.Id,1)]));Observe(0);flight=coordinator.Start(new("P22 exact evidence",PlanId:plan.Id));}
    void Observe(int second,bool paused=false){time=start.AddSeconds(second);var f=new TelemetryFrame(time,TelemetrySource.Simulated,"Explicit synthetic P22",40,-75,3000,null,120,120,120,0,0,0,0,0,paused);coordinator.Apply(new(new(ConnectionState.Connected,f.Source,"Synthetic",time),f,new(time,12+second*.1,29.9,5,270,.002)));}
    ResearchCardResult Control(ResearchCardAction action){var s=coordinator.PersonalResearch(flight.Id);return coordinator.ControlPersonalResearch(new(1,flight.Id,Guid.NewGuid(),s.Revision,action,card.Id,s.Cards[0].OpenAttempt?.Id));}
    RecordedResearchAttempt Attempt(){Control(ResearchCardAction.Activate);var id=Control(ResearchCardAction.BeginAttempt).Receipt.AttemptId!.Value;Observe(1);Observe(2);Observe(3);Control(ResearchCardAction.EndAttempt);return store.RecordedResearchAttempt(id);}
    MissionTimelinePage Page(MissionTimelineQuery? q=null)=>store.MissionTimeline(flight.Id,q??new(),science);
    [Theory][InlineData(false)][InlineData(true)]
    public void KeysetPagesHaveNoDuplicatesOrOmissionsAcrossEqualOriginalTimestamps(bool recent){for(var i=1;i<=35;i++)Observe(i);coordinator.End(flight.Id);var expected=new List<MissionTimelineReference>();string? largeCursor=null;do{var large=Page(new(Recent:recent,Limit:100,Cursor:largeCursor));expected.AddRange(large.Items.Select(x=>x.Reference));largeCursor=large.NextCursor;}while(largeCursor is not null);Assert.True(expected.Count>100);var all=new List<MissionTimelineReference>();string? cursor=null;do{var p=Page(new(Cursor:cursor,Recent:recent,Limit:7));Assert.InRange(p.Items.Length,1,7);all.AddRange(p.Items.Select(x=>x.Reference));cursor=p.NextCursor;}while(cursor!=null);Assert.Equal(expected,all);Assert.Equal(all.Count,all.Distinct().Count());}
    [Fact]public void CursorCannotCrossFlightOrFilterAndQueriesRemainBounded(){Observe(1);var p=Page(new(Limit:1));Assert.NotNull(p.NextCursor);Assert.Throws<ArgumentException>(()=>Page(new(Lane:MissionTimelineLane.Measurements,Cursor:p.NextCursor,Limit:1)));Assert.Throws<ArgumentException>(()=>Page(new(Limit:101)));Assert.Throws<ArgumentException>(()=>Page(new(Cursor:"invalid")));using var c=new CancellationTokenSource();c.Cancel();Assert.ThrowsAny<OperationCanceledException>(()=>store.MissionTimeline(flight.Id,new(),science,c.Token));}
    [Fact]public void OriginalAttemptLinksFrozenRevisionAndExactTelemetryWithoutNearestSubstitution(){var a=Attempt();coordinator.End(flight.Id);var saved=store.EvaluateRecordedResearchAttempt(a.Id,Guid.NewGuid());store.SaveResearchCard(new(card.Name,card.FlightRegime! with{AirspeedKnots=200},card.Id,1));var p=Page(new(Lane:MissionTimelineLane.ResearchCards,CardId:card.Id));var selected=Assert.Single(p.Items,x=>x.Reference.Id==a.BeginEventId.ToString());Assert.Equal(a.Id,selected.AttemptId);var detail=store.InspectTimeline(flight.Id,selected.Reference,science);Assert.Equal(a.Id,detail.Attempt!.Id);Assert.Equal(1,detail.Card!.Revision);Assert.Equal(saved.Id,detail.SavedResult!.Id);Assert.All(detail.ContextTelemetry!,x=>Assert.InRange(x.Frame.TimestampUtc,a.StartUtc,a.EndUtc!.Value));Assert.Equal(3,detail.ContextTelemetry!.Length);Assert.Contains(detail.Limitations!,x=>x.Contains("exact original attempt"));}
    [Fact]public void ScalarObservationVerifiesOriginalIntentPublicationInputAndSession(){Attempt();coordinator.End(flight.Id);var items=Page(new(Lane:MissionTimelineLane.Measurements,InstrumentId:"ambient-temperature")).Items;var row=items.First(x=>x.Reference.Source==MissionTimelineSource.ScienceObservation);var selected=store.InspectTimeline(flight.Id,row.Reference,science);Assert.Equal(row.Reference.Id,selected.Observation!.Id.ToString());Assert.Equal(ScienceProvenance.SimulatorReported,selected.Observation.Provenance);Assert.Equal(selected.Observation.IntentId,selected.Acquisition!.Intent.Id);Assert.Equal(selected.Observation.SessionId,selected.Session!.Id);Assert.Equal(selected.Acquisition.Intent.InputReceiptId,selected.OriginalInput!.Id);Assert.Equal(selected.Observation.TimestampUtc,selected.TimestampUtc);Assert.NotEmpty(selected.ContextMeasurements!);Assert.All(selected.ContextMeasurements!,x=>{Assert.Equal(row.Unit,x.Unit);Assert.Equal(row.Provenance,x.Provenance);});Assert.DoesNotContain(Page(new(CardId:card.Id)).Items,x=>x.Reference.Source==MissionTimelineSource.ScienceObservation);}
    [Fact]public void HashOrFlightSubstitutionNeverReturnsNearbyEvidence(){Observe(1);coordinator.End(flight.Id);var row=Page().Items.First(x=>x.Reference.Source==MissionTimelineSource.Telemetry);Assert.Throws<InvalidOperationException>(()=>store.InspectTimeline(flight.Id,row.Reference with{Sha256=new('0',64)},science));var next=coordinator.Start(new("Different flight",ScienceMode.Universal));Assert.Throws<InvalidOperationException>(()=>store.InspectTimeline(next.Id,row.Reference,science));Assert.Throws<InvalidOperationException>(()=>store.TimelineReference(flight.Id,MissionTimelineSource.Telemetry,"999999",science));}
    [Fact]public void OriginalEventTimeAndKindArePartOfTheEvidenceIdentity(){Observe(1);coordinator.End(flight.Id);var row=Page().Items.First(x=>x.Reference.Source==MissionTimelineSource.FlightEvent);using var db=new SqliteConnection("Data Source="+store.DatabasePath);db.Open();using var cmd=db.CreateCommand();cmd.CommandText="UPDATE events SET timestamp_utc=$utc WHERE id=$id";cmd.Parameters.AddWithValue("$id",long.Parse(row.Reference.Id));cmd.Parameters.AddWithValue("$utc",start.AddDays(1).ToString("O"));cmd.ExecuteNonQuery();Assert.Throws<InvalidOperationException>(()=>store.InspectTimeline(flight.Id,row.Reference,science));}
    [Fact]public void RestartRebuildsIdenticalTimelineWithoutSecondArchive(){Attempt();coordinator.End(flight.Id);var before=Page(new(Limit:100));var reopened=new MissionStore(store.DatabasePath){ScienceLibrary=science};reopened.Initialize();var after=reopened.MissionTimeline(flight.Id,new(Limit:100),science);Assert.Equal(before.Items,after.Items);Assert.Equal(before.NextCursor,after.NextCursor);Assert.Equal(1,reopened.RecordedOperations(flight.Id).Cards.Cards[0].Card.Revision);Assert.False(reopened.OperationsStatus(flight.Id).ScienceDeleted);}
    [Fact]public void PermanentScienceDeletionClearsOriginalAndDerivedScienceButPreservesFlightTimeline(){Attempt();coordinator.End(flight.Id);var original=Page(new(Lane:MissionTimelineLane.Measurements)).Items.First(x=>x.Reference.Source==MissionTimelineSource.ScienceObservation);var raw=store.StreamSamples(flight.Id).ToArray();var preview=science.PreviewCollectedDeletion(new([flight.Id]),store);Assert.Empty(preview.Blockers);Assert.Equal("Completed",science.DeleteCollectedScience(new(preview.Id,preview.SelectionHash),store,coordinator.EnterMaintenance).State);var page=Page();Assert.True(page.ScienceDeleted);Assert.DoesNotContain(page.Items,x=>x.Reference.Source==MissionTimelineSource.ScienceObservation);Assert.Throws<InvalidOperationException>(()=>store.InspectTimeline(flight.Id,original.Reference,science));Assert.Throws<InvalidOperationException>(()=>store.TimelineReference(flight.Id,MissionTimelineSource.ScienceObservation,original.Reference.Id,science));Assert.Equal(raw,store.StreamSamples(flight.Id));Assert.Empty(store.RecordedOperations(flight.Id).Operating);}
    [Fact]public void InterruptedAttemptRemainsInsufficientAndScienceSessionIsNotChangedByFocusFreeReads(){Control(ResearchCardAction.Activate);var id=Control(ResearchCardAction.BeginAttempt).Receipt.AttemptId!.Value;Observe(1,true);var collection=coordinator.ScienceCollection(flight.Id).State;for(var i=0;i<3;i++)Page(new(Limit:2));Assert.Equal(collection,coordinator.ScienceCollection(flight.Id).State);coordinator.Interrupt();var a=store.RecordedResearchAttempt(id);var p=store.TimelineReference(flight.Id,MissionTimelineSource.FlightEvent,a.BeginEventId.ToString(),science);Assert.Equal(ResearchAttemptStatus.Interrupted,store.InspectTimeline(flight.Id,p.Reference,science).Attempt!.Status);Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,store.EvaluateRecordedResearchAttempt(id,Guid.NewGuid()).Outcome);}
    [Fact]public void NativeActiveSummaryAndUtf8CommandRemainBounded(){Control(ResearchCardAction.Activate);var native=new ToolbarCommandHandler(coordinator);var packet=new ToolbarCommand(1,Guid.NewGuid(),"research-state",MissionId:flight.Id);var reply=native.Handle(JsonSerializer.Serialize(packet,WireJson.Options));Assert.InRange(Encoding.UTF8.GetByteCount(reply),1,8000);using(var doc=JsonDocument.Parse(reply)){Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());Assert.Equal(1,doc.RootElement.GetProperty("research").GetProperty("activeCardCount").GetInt32());}var oversized=JsonSerializer.Serialize(new{protocol=1,requestId=Guid.NewGuid(),op="marker",notes=new string('界',400)},WireJson.Options);using var rejected=JsonDocument.Parse(native.Handle(oversized));Assert.False(rejected.RootElement.GetProperty("ok").GetBoolean());}
    [Fact]public void LongRecordedFlightHasBoundedRecentAndWindowedTelemetryWithoutLoadingItsArchive(){var frame=coordinator.Snapshot().Telemetry!;for(var i=1;i<=5000;i++)store.Append(flight.Id,frame with{TimestampUtc=start.AddSeconds(i)});time=start.AddSeconds(5001);coordinator.End(flight.Id);var page=Page(new(Lane:MissionTimelineLane.Flight,Recent:true,Limit:50));Assert.Equal(50,page.Items.Length);Assert.NotNull(page.NextCursor);Assert.Contains(page.Items,x=>x.Reference.Source==MissionTimelineSource.Telemetry&&x.TimestampUtc==start.AddSeconds(5000));var exact=Page(new(FromUtc:start.AddSeconds(2500),ToUtc:start.AddSeconds(2502),Lane:MissionTimelineLane.Flight));Assert.Equal(3,exact.Items.Count(x=>x.Reference.Source==MissionTimelineSource.Telemetry));Assert.All(exact.Items,x=>Assert.InRange(x.TimestampUtc,start.AddSeconds(2500),start.AddSeconds(2502)));}
    [Fact]public void NotesAndMarkersUseOriginalIdsAndNeverInventMissingLocations(){var marker=store.AddMarker(flight.Id,new("observation","Original missing-position account"),start,null,null);var note=store.AddNote(flight.Id,new("Original independent note"));coordinator.End(flight.Id);var m=store.TimelineReference(flight.Id,MissionTimelineSource.PilotMarker,marker.Id.ToString(),science);var n=store.TimelineReference(flight.Id,MissionTimelineSource.ResearchNote,note.Id.ToString(),science);var inspected=store.InspectTimeline(flight.Id,m.Reference,science);Assert.Equal(marker.Id,inspected.Marker!.Id);Assert.Null(inspected.Marker.Latitude);Assert.Null(inspected.Marker.Longitude);Assert.Null(inspected.Marker.ScientificContextJson);Assert.Equal(note.Text,store.InspectTimeline(flight.Id,n.Reference,science).Note!.Text);}
    [Fact]public void OversizeOriginalFailsExplicitlyWithoutPresentingATruncatedVerifiedRecord(){store.AddEvent(flight.Id,start,"large-legacy-event",new string('x',300000));Assert.Throws<NotSupportedException>(()=>Page(new(Lane:MissionTimelineLane.ObservationsWarnings)));}
    public void Dispose(){if(store.Detail(flight.Id)?.Mission.Status==MissionStatus.Recording)coordinator.Interrupt();science.Dispose();SqliteConnection.ClearAllPools();Directory.Delete(root,true);}
}
